const items = [];

function parseRss(xmlText, category, source) {
  if (!xmlText || typeof xmlText !== 'string') return;
  const itemMatches = xmlText.matchAll(/<item>([\s\S]*?)<\/item>/gi);
  const now = Date.now();
  const maxAgeMs = 28 * 60 * 60 * 1000; // Max 28 jam (strictly fresh news cycle)

  for (const match of itemMatches) {
    const itemXml = match[1];
    const titleMatch = itemXml.match(/<title>([\s\S]*?)<\/title>/i);
    const linkMatch = itemXml.match(/<link>([\s\S]*?)<\/link>/i);
    const descMatch = itemXml.match(/<description>([\s\S]*?)<\/description>/i);
    const pubDateMatch = itemXml.match(/<pubDate>([\s\S]*?)<\/pubDate>/i);

    // Filter freshness: reject articles older than 28 hours
    if (pubDateMatch) {
      const pubTime = new Date(pubDateMatch[1]).getTime();
      if (!isNaN(pubTime) && (now - pubTime) > maxAgeMs) {
        continue;
      }
    }

    if (titleMatch && linkMatch) {
      const rawTitle = titleMatch[1].replace(/<!\[CDATA\[(.*?)\]\]>/gi, '$1').replace(/&amp;/g, '&').replace(/&quot;/g, '"').replace(/&#39;/g, "'").trim();
      const rawLink = linkMatch[1].replace(/<!\[CDATA\[(.*?)\]\]>/gi, '$1').trim();
      let rawDesc = descMatch ? descMatch[1].replace(/<[^>]*>?/gm, '').replace(/<!\[CDATA\[(.*?)\]\]>/gi, '$1').trim() : rawTitle;

      items.push({
        source,
        source_id: rawLink.slice(-32),
        title: rawTitle,
        content: rawDesc,
        url: rawLink,
        category,
        score: 100
      });
    }
  }
}

try {
  const indo = $('Fetch Google News Indo Celeb').first().json.data;
  parseRss(indo, 'seleb-lokal', 'google-news-indo');
} catch (e) {}

try {
  const soompi = $('Fetch Soompi K-Pop Feeds').first().json.data;
  parseRss(soompi, 'kpop-asia', 'soompi');
} catch (e) {}

try {
  const hollywood = $('Fetch Google News Hollywood').first().json.data;
  parseRss(hollywood, 'hollywood-barat', 'google-news-hollywood');
} catch (e) {}

// 1. Safety Pre-Filter
const forbidden = ['bunuh diri', 'porn', 'bokep', 'telanjang', 'gore', 'mutilasi', 'pedofil', 'meninggal', 'tewas', 'jenazah'];
const safeItems = items.filter(item => {
  const lower = (item.title + ' ' + item.content).toLowerCase();
  return !forbidden.some(word => lower.includes(word));
});

// 2. Persistent Workflow StaticData
const staticData = $getWorkflowStaticData('global');
if (!Array.isArray(staticData.dispatchedSignatures)) {
  staticData.dispatchedSignatures = [];
}
const dispatchedSet = new Set(staticData.dispatchedSignatures);

// 3. Fetch existing published articles from ngeghibah.com
let existingArticles = [];
try {
  const extData = $('Fetch Published Articles from NgeGhibah').first().json;
  existingArticles = extData.articles || [];
} catch (e) {}

const stopwords = new Set([
  'yang', 'untuk', 'pada', 'dari', 'dalam', 'dan', 'atau', 'ini', 'itu',
  'juga', 'ada', 'bisa', 'akan', 'oleh', 'saat', 'para', 'ke', 'di',
  'terkait', 'hingga', 'kupas', 'tuntas', 'fakta', 'viral', 'bukan',
  'sekadar', 'deretan', 'deret', 'simak', 'bikin', 'potret', 'resmi',
  'lengkap', 'kronologi', 'jejak', 'digital', 'analisis', 'spekulasi',
  'verifikasi', 'duduk', 'perkara', 'isu', 'kabar', 'terbaru', 'tahun',
  'soal', 'kembali', 'usai', 'klaim', 'tampil', 'aksi', 'seputar', 'antara'
]);

function cleanWords(text) {
  return (text || '').toLowerCase().replace(/[^a-z0-9\s]/g, '').split(/\s+/).filter(w => w.length > 2 && !stopwords.has(w));
}

const existingTokenSets = existingArticles.map(a => new Set(cleanWords(a.title || '')));

function isDuplicate(candTitle) {
  const candWords = cleanWords(candTitle);
  if (candWords.length === 0) return true;
  const candSet = new Set(candWords);

  for (const extSet of existingTokenSets) {
    let inter = 0;
    for (const w of candSet) {
      if (extSet.has(w)) inter++;
    }
    const union = new Set([...candSet, ...extSet]).size || 1;
    const jaccard = inter / union;
    // Jaccard >= 0.45 or > 50% candidate overlap -> reject as duplicate event
    if (jaccard >= 0.45 || (inter / candWords.length) >= 0.50) {
      return true;
    }
  }
  return false;
}

// 4. Intra-batch & Persistent Deduplication
const seenSignatures = new Set();
const freshCandidates = [];

for (const item of safeItems) {
  const cleanTitle = item.title.toLowerCase().replace(/[^a-z0-9]/g, '').slice(0, 36);
  if (seenSignatures.has(cleanTitle)) continue;
  seenSignatures.add(cleanTitle);

  if (dispatchedSet.has(cleanTitle) || dispatchedSet.has(item.source_id)) {
    continue;
  }

  if (isDuplicate(item.title)) {
    continue;
  }

  item.event_signature = cleanTitle;
  freshCandidates.push(item);
}

if (freshCandidates.length === 0) {
  return [];
}

const chosen = freshCandidates[0];
staticData.dispatchedSignatures.push(chosen.event_signature, chosen.source_id);
if (staticData.dispatchedSignatures.length > 400) {
  staticData.dispatchedSignatures = staticData.dispatchedSignatures.slice(-400);
}

return [{ json: chosen }];
